import { CONTRACTS } from './chain-config.js';
import { ethers, getProvider, sendTx } from './contracts.js';
import { get, deriveCanSign } from './store.js';
import { permissionlessReadProvider, readProviderBlockNumber } from './read-provider.js';
import { requireStaticCall } from './static-call.js';
import { deriveDeityBoonSlots } from './passes.js';
import { fetchJSON } from './api.js';

// Working-tree contracts: Vault/sDGNRS.donateFlipForBoons → BoonModule.
// Both altars take FLIP. Their symbols identify the deity, not the payment asset.
export const SACRIFICE_DEITIES = Object.freeze([
  { key: 'vault', address: CONTRACTS.VAULT, name: 'WWXRP', keeper: 'The vault', symbol: '/badges-circular/crypto_00_xrp_red.svg' },
  { key: 'sdgnrs', address: CONTRACTS.SDGNRS, name: 'ETH', keeper: 'sDGNRS', symbol: '/badges-circular/crypto_06_ethereum_green.svg' },
]);
export const FLIP_UNIT = 10n ** 18n;
export const MIN_SACRIFICE = 100n * FLIP_UNIT;
export const MAX_SACRIFICE = 25_000n * FLIP_UNIT;
const GAME_ABI = [
  'function currentDayView() view returns (uint24)',
  'function rngWordForDay(uint24 day) view returns (uint256)',
  'function gameOverTimestamp() view returns (uint48)',
  'function livenessTriggered() view returns (bool)',
];
const LENS_ABI = [
  'function protocolBoonPool(address game,address issuer,uint24 day) view returns (tuple(uint112 totalDonatedWei,uint64 totalWeight,uint32 entryCount,uint8 awardedMask) pool)',
  'function protocolBoonQuote(address game,address donor,uint256 amount) view returns (uint8 amountUnits,uint16 score,uint16 multiplierUnits,uint64 weight)',
];
const DONATE_ABI = ['function donateFlipForBoons(uint256 amount)'];
const ENTRY_ABI = ['event ProtocolBoonDrawEntered(address indexed issuer,address indexed donor,uint24 indexed day,uint256 amount,uint8 amountUnits,uint16 scoreSnapshot,uint64 weight,uint32 entryIndex)'];
let contractFactory = (address, abi, runner) => new ethers.Contract(address, abi, runner);

export function parseSacrificeAmount(value) {
  const text = String(value ?? '').trim();
  if (!/^\d+(?:\.\d{1,18})?$/.test(text)) return null;
  try { return ethers.parseEther(text); } catch { return null; }
}

/** The three protocol slots a funded pool always draws, with replacement. */
export const SACRIFICE_SLOTS_PER_POOL = 3;

/**
 * Read-only history for one wallet: its entries and the slots it has won.
 *
 * ⛔ CODE DEFENSIVELY. The route is served by the indexer, which publishes it
 * independently of this build, so a 404 means "no history surface yet" and NOT
 * "this wallet has never entered". Every failure degrades to an empty, explicitly
 * UNAVAILABLE result, and the altar keeps working on chain reads alone.
 *
 * Row shapes, as the route serves them (both halves are always ARRAYS, never null,
 * and the wide fields stay STRINGS because `amount` is a uint256 and `weight` a uint64):
 *   entries[] { issuer, player, day, amount, units, amountUnits, scoreSnapshot,
 *               weight, entryIndex, blockNumber, transactionHash, logIndex }
 *   awards[]  { issuer, player, day, slot, entryIndex, boonKind, boonType,
 *               blockNumber, transactionHash, logIndex }
 * A donor who won nothing still appears in `entries` — that population is the whole
 * point of publishing the weighting, so never infer "no entry" from an empty `awards`.
 *
 * @returns {Promise<{available:boolean, entries:Array<object>, awards:Array<object>}>}
 */
export async function readSacrificeHistory(player, { limit = 25, signal, force = false } = {}) {
  const empty = Object.freeze({ available: false, entries: [], awards: [] });
  const wallet = String(player ?? '').trim();
  if (!ethers.isAddress(wallet)) return empty;
  // The route rejects a limit outside 1..500 with a 400 rather than scanning.
  const count = Math.max(1, Math.min(500, Math.trunc(Number(limit)) || 25));
  let payload = null;
  try {
    // ⛔ NO `/api` PREFIX. `fetchJSON` prepends CHAIN.indexerBase, and the indexer
    // registers the game routes under `/game` (server.ts), exactly like the
    // `/game/jackpot/last-day` payload this app already reads.
    payload = await fetchJSON(
      `/game/protocol-boon-draws?player=${wallet.toLowerCase()}&limit=${count}`,
      { signal, force },
    );
  } catch (_error) {
    // 404 (route not deployed), 5xx, offline, abort — all the same to the altar.
    return empty;
  }
  if (!payload || typeof payload !== 'object') return empty;
  const rows = (value) => (Array.isArray(value) ? value.filter((row) => row && typeof row === 'object') : []);
  return Object.freeze({
    available: true,
    entries: Object.freeze(rows(payload.entries)),
    awards: Object.freeze(rows(payload.awards)),
  });
}

/** Lowercase one address-ish value; '' when it is not one. */
function _addr(value) {
  const text = String(value ?? '').trim().toLowerCase();
  return /^0x[0-9a-f]{40}$/.test(text) ? text : '';
}

/**
 * Fold a wallet's OWN entries for one issuer and one pool day.
 *
 * A donor may enter the same pool repeatedly, and every entry keeps its own frozen
 * score snapshot, so the standing is the SUM of their weights — not a re-quote at
 * today's score. Returns zeroes (never null) so a panel can render before history
 * loads without branching.
 */
export function sacrificeStanding(entries, { issuer, day } = {}) {
  const wantIssuer = _addr(issuer);
  const wantDay = Number(day);
  let weight = 0n;
  let units = 0;
  let amountWei = 0n;
  let count = 0;
  for (const row of Array.isArray(entries) ? entries : []) {
    if (wantIssuer && _addr(row.issuer) !== wantIssuer) continue;
    if (Number.isInteger(wantDay) && Number(row.day) !== wantDay) continue;
    count += 1;
    try { weight += BigInt(row.weight ?? 0); } catch { /* malformed row */ }
    try { amountWei += BigInt(row.amount ?? 0); } catch { /* malformed row */ }
    const rowUnits = Number(row.units ?? row.amountUnits ?? 0);
    if (Number.isFinite(rowUnits)) units += rowUnits;
  }
  return Object.freeze({ count, units, weight, amountWei });
}

/**
 * Chance that a weight wins AT LEAST ONE of the pool's three slots.
 *
 * Each slot is an independent weighted draw WITH REPLACEMENT over the same pool, so
 * one donor can take all three and the per-slot chances do not simply add.
 */
export function sacrificeAnySlotChance(weight, totalWeight) {
  let mine = 0n;
  let total = 0n;
  try { mine = BigInt(weight ?? 0); total = BigInt(totalWeight ?? 0); } catch { return null; }
  if (mine <= 0n || total <= 0n || mine > total) return mine > 0n && mine === total ? 1 : null;
  const perSlot = Number(mine) / Number(total);
  return 1 - ((1 - perSlot) ** SACRIFICE_SLOTS_PER_POOL);
}

export function sacrificeQuote(amount, multiplierUnits, poolWeight) {
  if (amount == null || multiplierUnits == null || poolWeight == null) return null;
  const wei = BigInt(amount);
  const multiplier = BigInt(multiplierUnits);
  const total = BigInt(poolWeight);
  if (wei < MIN_SACRIFICE || wei > MAX_SACRIFICE || multiplier < 800n || multiplier > 2400n || total < 0n) return null;
  const units = wei / MIN_SACRIFICE;
  const weight = units * multiplier;
  return {
    units: Number(units), weight, multiplier: Number(multiplier) / 800,
    remainderWei: wei % MIN_SACRIFICE,
    // This entry's chance, after adding it to the currently observed pool.
    // Existing entries belonging to the same donor are deliberately not included.
    chance: Number(weight) / Number(total + weight),
  };
}

/** Read one coherent block; tomorrow's menu uses TODAY's word and day + 1. */
export async function readSacrifices({ player = null } = {}) {
  const provider = permissionlessReadProvider(getProvider());
  if (!provider || !CONTRACTS.GAME_LENS || SACRIFICE_DEITIES.some((d) => !d.address)) return null;
  const game = contractFactory(CONTRACTS.GAME, GAME_ABI, provider);
  const lens = contractFactory(CONTRACTS.GAME_LENS, LENS_ABI, provider);
  const blockTag = await readProviderBlockNumber(provider);
  const opts = { blockTag };
  const [dayRaw, ended, timedOut, wallet] = await Promise.all([
    game.currentDayView(opts), game.gameOverTimestamp(opts), game.livenessTriggered(opts),
    player ? Promise.all([
      contractFactory(CONTRACTS.COIN, ['function balanceOf(address) view returns (uint256)'], provider).balanceOf(player, opts),
      lens.protocolBoonQuote(CONTRACTS.GAME, player, MIN_SACRIFICE, opts),
    ]).catch(() => null) : null,
  ]);
  const day = Number(dayRaw);
  if (!Number.isInteger(day) || day < 1 || day >= 0xffffff) return null;
  const [seed, pools] = await Promise.all([
    game.rngWordForDay(day, opts),
    Promise.all(SACRIFICE_DEITIES.map(async (deity) => {
      const pool = await lens.protocolBoonPool(CONTRACTS.GAME, deity.address, day, opts);
      return {
        key: deity.key,
        totalDonatedWei: BigInt(pool.totalDonatedWei ?? pool[0]),
        totalWeight: BigInt(pool.totalWeight ?? pool[1]),
        entryCount: Number(pool.entryCount ?? pool[2]),
        awardedMask: Number(pool.awardedMask ?? pool[3]),
      };
    })),
  ]);
  return {
    day, awardDay: day + 1, menuReady: BigInt(seed) !== 0n,
    ended: BigInt(ended) !== 0n || Boolean(timedOut),
    balanceWei: wallet ? BigInt(wallet[0]) : null,
    multiplierUnits: wallet ? Number(wallet[1].multiplierUnits ?? wallet[1][2]) : null,
    score: wallet ? Number(wallet[1].score ?? wallet[1][1]) : null,
    pools: pools.map((pool, index) => ({
      ...pool,
      slots: deriveDeityBoonSlots({ dailySeed: seed, deity: SACRIFICE_DEITIES[index].address, day: day + 1, includeCraps: true }),
    })),
  };
}

function requireDonor(expected) {
  const connected = String(get('connected.address') || '').toLowerCase();
  // Wrappers charge msg.sender; they cannot donate on an operator's behalf.
  if (get('ui.mode') !== 'self' || !deriveCanSign() || !connected || connected !== expected) {
    throw new Error('Open your own connected wallet to sacrifice FLIP.');
  }
}

export async function sacrificeFlip({ deityKey, amount, expectedDay, onSubmitted } = {}) {
  const deity = SACRIFICE_DEITIES.find((item) => item.key === deityKey);
  if (!deity?.address) throw new Error('Choose a deity.');
  let wei;
  try { wei = BigInt(amount); } catch { throw new Error('Enter a FLIP amount.'); }
  if (wei < MIN_SACRIFICE || wei > MAX_SACRIFICE) throw new Error('Sacrifice 100–25,000 FLIP per entry.');
  if (!Number.isInteger(expectedDay) || expectedDay < 1 || expectedDay >= 0xffffff) throw new Error('Refresh tomorrow’s boons first.');
  const donor = String(get('connected.address') || '').toLowerCase();
  requireDonor(donor);
  const receipt = await sendTx(async (signer) => {
    requireDonor(donor);
    if (String(await signer.getAddress()).toLowerCase() !== donor) throw new Error('Wallet changed. Review your sacrifice again.');
    const game = contractFactory(CONTRACTS.GAME, GAME_ABI, signer);
    if (Number(await game.currentDayView()) !== expectedDay) throw new Error('The game day changed. Review the new boons before sacrificing.');
    const sink = contractFactory(deity.address, DONATE_ABI, signer);
    const sim = await requireStaticCall(sink, 'donateFlipForBoons', [wei], signer);
    if (!sim.ok) throw sim.error;
    requireDonor(donor);
    if (Number(await game.currentDayView()) !== expectedDay) throw new Error('The game day changed. Review the new boons before sacrificing.');
    return sink.donateFlipForBoons(wei);
  }, `Sacrifice FLIP to ${deity.name}`, { onSubmitted });
  // The wrapper has no expected-day parameter. A transaction mined over reset
  // enters the new day: report the emitted day rather than the preview's day.
  const iface = new ethers.Interface(ENTRY_ABI);
  let entryDay = null;
  for (const log of receipt?.logs ?? []) {
    if (String(log.address).toLowerCase() !== CONTRACTS.GAME.toLowerCase()) continue;
    try {
      const event = iface.parseLog(log);
      if (event?.name === 'ProtocolBoonDrawEntered'
        && event.args.donor.toLowerCase() === donor
        && event.args.issuer.toLowerCase() === deity.address.toLowerCase()) entryDay = Number(event.args.day);
    } catch { /* other receipt events */ }
  }
  return { receipt, entryDay, awardDay: entryDay == null ? null : entryDay + 1 };
}

export function __setSacrificeContractFactoryForTest(factory) {
  contractFactory = factory || ((address, abi, runner) => new ethers.Contract(address, abi, runner));
}
